mapper.select:
select distinct po.platform_order_id
from platform_order po
where po.order_time > '2025-09-01'
  and po.platform_order_id not in (select platform_order_id from shouman_order)
and po.order_time >= #{beginOrderTime}
and po.order_time <= #{endOrderTime}
and po.shop_id = #{shopId}

    and po.platform_order_number in

        #{orderNumber}


order by po.order_time, po.platform_order_id
